以下代码中 len(c) 会触发属性访问增加 _count，最终打印什么？
```python
class CountAccess:
    def __init__(self, obj):
        self._obj = obj
        self._count = 0
    def __getattribute__(self, name):
        if name in ('_obj', '_count', 'get_count'):
            return object.__getattribute__(self, name)
        object.__setattr__(self, '_count', object.__getattribute__(self, '_count') + 1)
        return getattr(object.__getattribute__(self, '_obj'), name)
    def get_count(self):
        return object.__getattribute__(self, '_count')
c = CountAccess([1, 2, 3])
len(c)
print(c.get_count())
```

